    GZ_ASSERT(
      _currConstBufferIdx <= _constBuffers.size() &&
        _startMappedConstBuffer != nullptr,
      "This should not happen. Base class must've bound something");

    this->lastMainConstBuffer = _constBuffers[_currConstBufferIdx];

    BindObjectDataBuffer(_commandBuffer, _perObjectDataBufferSlot);
  }
```

All I did was add a `if (_currConstBufferIdx >= this->perObjectDataBuffers.size())` check and then later `Ogre::ConstBufferPacked *constBuffer = this->perObjectDataBuffers[_currConstBufferIdx];`


